# --- 検証(1問=正しい肢1つ / 全引用が原文に含まれる) ---
bad = []; rows = []; md_q = []; md_a = []
for i, (topic, amend, stem, kk) in enumerate(Q, 1):
    assert len(kk) == 4 and sum(k[1] for k in kk) == 1, f"PQ-{i:02d}: 正しい肢が1つでない"
    ans = [j for j, k in enumerate(kk, 1) if k[1]][0]
    cites, quotes = [], []
    for j, (txt, tf, ex, refs) in enumerate(kk, 1):
        assert refs, f"PQ-{i:02d}-{j}: 根拠なし"
        for src, art, p, q in refs:
            ok = T(ET.fromstring(f"<x>{q}</x>")) in para(src, art, p)
            if not ok: bad.append((f"PQ-{i:02d}-{j}", cite(src, art, p), q[:40]))
            cites.append(f"肢{j}:{cite(src,art,p)}"); quotes.append(f"肢{j}:「{q}」")
    rows.append([f"PQ-{i:02d}", topic, amend, stem] + [k[0] for k in kk] + [ans, " / ".join(f"肢{j}={'正' if k[1] else '誤'}:{k[2]}" for j, k in enumerate(kk, 1)), " ; ".join(cites), " ; ".join(quotes), "原文一致(e-Gov 2026-09-30取得)"])
    md_q.append(f"### 問{i}(PQ-{i:02d} / 論点{topic}・改正{amend})\n\n{stem}\n\n" + "\n".join(f"{j}. {k[0]}" for j, k in enumerate(kk, 1)) + "\n")
    md_a.append(f"### 問{i} 正解:{ans}\n\n" + "\n".join(f"- 肢{j}【{'正' if k[1] else '誤'}】{k[2]} 〔根拠:{'、'.join(dict.fromkeys(cite(*r[:3]) for r in k[3]))}〕" for j, k in enumerate(kk, 1)) + "\n")
assert not bad, f"原文に見つからない引用: {bad}"
os.makedirs("06_練習問題", exist_ok=True)
with open("06_練習問題/練習問題_改正区分所有法.csv", "w", encoding="utf-8-sig", newline="") as f:
    w = csv.writer(f); w.writerow(["問題ID", "論点ID", "関連改正ID", "問題文", "肢1", "肢2", "肢3", "肢4", "正解", "解説(肢別)", "根拠条文", "根拠原文(抜粋)", "検証"]); w.writerows(rows)
head = ("# 練習問題:改正区分所有法の論点(全%d問)\n\n- 作成:AI(Sonnet)。**本試験の過去問ではなく、練習用の創作問題**。\n- 根拠:e-Gov法令検索の条文データ(2026-09-30取得、`01_原本/法令データ/`)。全肢について、根拠の条・項と原文の一部が原文に含まれることをコードで検証済み(`scripts/make_practice_questions.py`)。\n- 出題基準日:令和8年4月1日施行の法令等。改正区分所有法は同日施行。\n- 限界:問題の切り口・難易度は本試験と異なる。条文の言い換え部分の妥当性は人の確認を推奨。\n\n" % len(Q))
open("06_練習問題/練習問題_改正区分所有法.md", "w", encoding="utf-8").write(head + "## 問題\n\n" + "\n".join(md_q) + "\n---\n\n## 正解と解説\n\n" + "\n".join(md_a))
